from itertools import groupby
from typing import List

def maximumEfficiency(arrivalTime: List[int]) -> float:
    groups = [(t, len(list(g))) for t, g in groupby(sorted(arrivalTime))]
    if len(groups) < 2:
        return float("inf")       # all tests at one instant: zero active time
    return max((c1 + c2) / (t2 - t1) for (t1, c1), (t2, c2) in zip(groups, groups[1:]))
